            [5725] = "Apporter les livres de Sorts des Ombres et d’Incantations du Néant à Varimathras, à Fossoyeuse.",
            [5726] = "Apporter un Insigne de lieutenant à Thrall à Orgrimmar.",
            [5727] = "Apporter l'Insigne du Lieutenant à Neeru Fireblade et lui parler. Essayer de déterminer s'il vous croit membre de la Lame ardente puis retourner voir Thrall à Orgrimmar.",
            [5728] = "Tuer Bazzalan et Jergosh l'Invocateur avant de retourner voir Thrall à Orgrimmar.",
            [5729] = "Parler à Neeru Fireblade à Orgrimmar.",
            [5730] = "Parler à Thrall à Orgrimmar et lui dire ce que vous avez appris.",
            [5761] = "Pénétrer dans le Gouffre de Ragefeu et tuer Taragaman l'Affameur, puis rapporter son coeur à Neeru Fireblade à Orgrimmar.",
            [6521] = "Apporter la Tête de l'Ambassadeur Malcin à Varimathras, à Fossoyeuse.",
            [6522] = "Apporter le Petit parchemin à Varimathras, à Fossoyeuse.",
            [6561] = "Apporter la tête du Seigneur du crépuscule Kelris à Bashana Runetotem, à Thunder Bluff.",
            [6562] = "Parler à Je'neu Sancrea, à Ashenvale.",
            [6563] = "Apporter 20 Saphirs d'Aku'Mai à Je'neu Sancrea, à Ashenvale.",
            [6564] = "Apporter la Note humide à Je'neu Sancrea, à Ashenvale.",
            [6565] = "Tuer Lorgus Jett, dans les Profondeurs de Brassenoire et retourner voir Je'neu Sancrea, à Ashenvale.",
            [6626] = "Tuer 8 Gardes de guerre Tranchebauge, 8 Tisseurs d'épines Tranchebauge et 8 Sectateur de la Tête de mort, puis retourner voir Myriam Moonsinger, à l’entrée des Souilles de Tranchebauge.",
            [6627] = "Réussir à répondre à la question de Braug Dimspirit, puis lui reparler. Il se trouve dans les Serres-Rocheuses.",
            [6628] = "Réussir à répondre à la question de Parqual Fintallas, puis lui reparler. Il se trouve à Fossoyeuse.",
            [6921] = "Apporter le Noyau de la brasse à Je'neu Sancrea, à l’Avant-poste de Zoram'gar, dans Ashenvale.",
            [92401] = "Enquêtez sur la disparition d’Edward Tissecœur dans les ruines de Lordaeron.",
            [92415] = "Apportez la lettre tachée de sang à la directrice de l’orphelinat Rossignol, à Hurlevent.",
            [92421] = "Récupérez 25 membres intacts dans les ruines de Lordaeron pour Morbin Plaie-lumineuse, à Fossoyeuse.",
            [92422] = "Tuez Rath’mael, dans les ruines de Lordaeron, pour le nécrogarde Kristof, à Brill.",
            [92742] = "Utilisez le kit d’échantillonnage d’eau de puits pour collecter des échantillons dans les puits de la ferme des Jansen et de la ferme des Molsen.",
            [92744] = "Alba Lunepâle vous demande de récupérer 7 branchies de Murloc de Longrivage sur les côtes de la marche de l’Ouest.",
            [92745] = "Tuez 4 terrassiers kobold à la mine Veine-de-Jango et 6 mineurs Rivepatte à la carrière de la côte de l’Or.",
            [92747] = "Récupérez 8 fournitures d’ingénierie suspectes à Ruisselune.",
            [92748] = "Rendez-vous au quartier des Nains à Hurlevent et cherchez un ingénieur pour vous aider.",
            [92749] = "Obtenez 10 dynamites grossières en les fabriquant, en les échangeant ou à l’hôtel des ventes, puis retournez voir Fée Dérailleur dans le quartier des Nains, à Hurlevent.",
            [92750] = "Parlez à une personne du renseignement de Hurlevent pour obtenir un détonateur à distance.",
            [92751] = "Apportez le kit de détonateur à distance à Fée Dérailleur, au quartier des Nains de Hurlevent.",
            [92752] = "Retournez voir Alba Lunepâle à la marche de l’Ouest.",
            [92753] = "Trouvez la forge cachée dans les Mortemines et placez les explosifs de destruction ultime à proximité. Rejoignez ensuite Alba Lunepâle à la sortie des Mortemines.",
            [92819] = "Utilisez le détonateur.",
            [95161] = "Remettez la lettre tachée de sang à Avette Boichu dans le bois de la Pénombre.",
            [95189] = "Rendez l’écu de Lordaeron à dame Dena Kennedy, à Hurlevent.",
            [95195] = "Récupérez 10 insignes ensanglantés et remettez-les au général Marcus Jonathan, à Hurlevent.",
            [95204] = "Rapportez l’écu de Lordaeron à Oran Serpenroule, à Fossoyeuse.",
            [95216] = "Récupérez la souche hautement toxique auprès de Croc-Flétri dans les ruines de Lordaeron, pour Theodore Griffs, à Fossoyeuse.",
            [95250] = "Récupérez la tête du baron dans les ruines de Lordaeron et rapportez-la au capitaine Truman.",
            [95646] = "Tuez une horreur des hautes-terres dans les excavations et rapportez son cœur-racine à Rethiel le Gardien vert dans les Paluns.",
            [95647] = "Trouver Ardin Grassman dans les excavations",
            [95663] = "Rendez-vous dans les Paluns et retrouvez l’agente nécrotraqueuse dans les collines qui dominent le campement gueule-de-dragon.",
            [95664] = "Apportez la relique des Titans à la cime des Anciens, aux Pitons-du-Tonnerre, et cherchez quelqu’un qui saura vous en apprendre davantage à son sujet.",
            [95682] = "Éliminez les forces des Gueules-de-dragon présentes sur le site de fouilles, puis retournez auprès de l’agent des nécrotraqueurs à l’extérieur et remettez-lui tout ce que vous aurez récupéré.",
            [95697] = "Pénétrez dans les excavations des Paluns et rapportez de la viande de raptor des fourrés.",
            [95737] = "Parlez à Caitlin Grassman au port de Menethil.",
            [95772] = "Cherchez Daewyn, le frère de Dorin Lame-chantante, dans les Excavations de Whelgar.",
            [95795] = "Retournez voir Dorin Lame-chantante",
            [95809] = "Retourner voir Caitlin Grassman au port de Menethil",
            [95810] = "Apportez la relique des Titans au prospecteur Whelgar sur le site de fouilles des Paluns.",
            [96391] = "Remettez la carte sombrefer au terre-voyant Farsen, à Dun Morogh.",
            [96393] = "Pénétrez dans la salle des Thanes, sous le Vieux Forgefer, et emparez-vous de la tête de Durgen Mornemartel.",
            [96394] = "Tuez 15 apparitions enragées et 10 âmes tourmentées, puis accordez le repos à l’esprit de Courbenclume.",
            [96395] = "Apaisez l’esprit de Faldrim Courbenclume, puis retournez voir le domestique fantomatique dans la salle des Thanes.",
            [96403] = "Récupérez 8 héritages nains dans la salle des Thanes.",
            [97288] = "Apportez la tête abominable au maître apothicaire Faranell à Fossoyeuse.",
            [97289] = "Apportez la tête du baron au corps d’Othmar, à Fossoyeuse.",
            [97290] = "Faites votre rapport au maître apothicaire Faranell, à Fossoyeuse.",
            [97291] = "Récupérez un calot toxique auprès de Grisette Fauve dans le quartier des Marchands, de la cloquette auprès de la maîtresse des herboristes et de l’essence d’agonie auprès du marchand de poison du quartier des Voleurs, pour le maître apothicaire Faranell à Fossoyeuse.",
            [97292] = "Injectez le sérum sifflant dans le dispositif au-dessus du corps d’Othmar, pour le maître apothicaire Faranell.",
            [98423] = "Remettez le traité de l’entente à Magni Barbe-de-Bronze, à Forgefer.",
            [98815] = "Rapportez 4 peaux de raptor des fourrés à James Halloran, le tanneur, au port de Menethil.",
            [98823] = "Apportez la relique des Titans à Muln Rageterre, sur le plateau de Guette-ciel au nord-ouest de Mulgore.",
            [98824] = "Apportez la relique des Titans au Grand Explorateur Magellas, dans le hall des Explorateurs de Forgefer.",
        },
