        desc = {
            ALCAZ = "Ile d'Alcaz : une prison où Confrérie défias retenait jadis des nobles contre rançon, aujourd’hui assiégée par les nagas.",
            BARROW = "Un vaste réseau de tertres des elfes de la nuit qui retient les prisonniers les plus dangereux du monde, et la corruption se répand.",
            BFD = "La grève de Zoram : un temple elfe de la nuit inondé, désormais tenu par des nagas, des satyres et des cultistes au service de Aku'mai.",
            BLACKMAW = "Azshara, nord : une grande cité furbolg qui lutte contre sa propre corruption. Ses tunnels s’enfoncent jusqu’à Profondeurs des Saisons.",
            BRD = "Mont Rochenoire : sous la montagne s’étend la capitale en fusion de Nains Sombrefer, gouvernée par Empereur Dagran Thaurissan.",
            DAL = "La barrière de Kirin Tor faiblit, et la cité violette est envahie par des enchantements déchaînés, des assemblages arcaniques et des fuites d’énergie démoniaque.",
            DM = "Sous les mines abandonnées de Ruisselune, Confrérie défias construit un mastodonte pour frapper Hurlevent. Son chef : Edwin VanCleef.",
            DME = "Les jardins orientaux envahis par la végétation d’une ancienne cité elfe, où Alzzin le Modeleur corrompt les arbres anciens.",
            DMN = "Les ogres se sont emparés des cours nord d’une ancienne cité elfe. Leur chef : Roi Gordok. Vainquez-le et réclamez leur tribut.",
            DMW = "Dans l’aile ouest, les Bien-nés drainent le démon Immol'thar, sous les ordres de Prince Tortheldrin.",
            DROWNED = "Vallée de Strangleronce : des ruines trolls englouties ont surgi de la mer au large, et trolls, nagas et pirates se disputent ce qu’elles renferment.",
            EXC = "Une fouille de la Ligue des explorateurs a percé d’anciennes salles des titans : brume étrange, éclairs de lumière et assemblages toujours en faction.",
            GNOMER = "La capitale irradiée des gnomes, perdue face aux troggs et à la trahison de Mekgénieur Thermaplugg.",
            HOT = "Forgefer : sous la vieille cité, des intrus de Nains Sombrefer ont pénétré dans les tombeaux royaux des anciens thanes, et les morts sans repos se sont réveillés.",
            HYJAL = "Mont Hyjal : quelque chose draine la puissance des terres alentour, où errent encore les fantômes d’une guerre ancienne.",
            KROLDOK = "Une immense forteresse ogre dont les pillards font des prisonniers, et dont les chants nocturnes trahissent un lien avec des cultistes.",
            LBRS = "Les salles inférieures d’une forteresse d’orcs et d’ogres, sous les ordres de Seigneur Wyrmthalak. Dix joueurs dans Forever.",
            MARA = "Désolace : une caverne sacrée des centaures, corrompue par l’élémentaire de terre Princesse Theradras.",
            ONY = "Onyxia, fille du grand dragon noir, attend dans son repaire (Marécage d'Âprefange). Débloqué avec le premier palier de raid de Forever.",
            RFC = "Orgrimmar : dans les cavernes volcaniques sous la ville, troggs et cultistes (Lame ardente) complotent dans l’ombre, et Horde est menacée.",
            RFD = "Les anciens tertres funéraires des huranes sont tombés aux mains du Fléau, mené par la liche Amnennar le Porte-froid.",
            RFK = "Les Tarides, sud : un labyrinthe épineux, foyer des huranes et de leur prêtresse Charlga Trancheflanc.",
            ROL = "Le Fléau tient toujours la capitale en ruine au-dessus de Fossoyeuse, où un nécromancien amasse du pouvoir parmi les cendres.",
            SCHOLO = "Caer Darrow : dans les cryptes sous le château, des cultistes ont fondé une école de nécromancie, dirigée par Sombre Maître Gandling.",
            SFK = "Forêt des Pins argentés (Silverpine Forest) : Archimage Arugal et ses worgens tiennent le donjon, et leur malédiction se répand toujours plus loin.",
            SHAPER = "Cratère d'Un'Goro : dans les collines se dresse une installation des titans intacte, vibrant de cristaux de puissance et d’une énergie inexplicable.",
            SMARM = "L’arsenal de l’ordre (Croisade écarlate) est gardé par son champion, Herod.",
            SMCATH = "Au cœur du monastère, Commandant écarlate Mograine et Grand Inquisiteur Whitemane mènent les fanatiques.",
