            ["Stop"] = "Arrêter",
            ["Stopped."] = "Arrêté.",
            ["Strength"] = "Force",
            ["Subtlety"] = "Finesse",
            ["Survival"] = "Survie",
            ["Switch it on for your Best in Slot set, the next upgrades, the simulator and the upgrade check for loot. The settings have it too (Modules)."] = "Activez-le pour votre ensemble Best in Slot, les prochaines améliorations, le simulateur et le test d’amélioration du butin. Les réglages l’ont aussi (Modules).",
            ["Switch off the pages you do not use. Best in Slot and Wishlist also take their marks, tooltip lines and alerts with them. One module always stays on."] = "Désactivez les pages que vous n’utilisez pas. Best in Slot et Liste de souhaits emportent aussi leurs marques, lignes d’infobulle et alertes. Un module reste toujours activé.",
            ["Switch off what you do not use: its tab goes away, Best in Slot also takes its crowns and tooltip lines with it, Wishlist its stars, tooltip mark and alerts. One module always stays on. The database look has its own pages."] = "Désactivez ce que vous n’utilisez pas : son onglet disparaît, Best in Slot emporte aussi ses couronnes et lignes d’infobulle, la Liste de souhaits ses étoiles, sa marque d’infobulle et ses alertes. Un module reste toujours activé. Le style Base de données a ses propres pages.",
            ["Switch on Best in Slot"] = "Activer Best in Slot",
            ["Sword"] = "Épée",
            ["TANK"] = "TANK",
            ["TURN IN"] = "À RENDRE",
            ["Tabard"] = "Tabard",
            ["Tailoring"] = "Couture",
            ["Taken from the English collect, not asked: %d items without data, %d refused quests."] = "Repris de la collecte anglaise, non demandés : %d objets sans données, %d quêtes refusées.",
            ["Takes every item out of this set."] = "Retire tous les objets de cet ensemble.",
            ["Talents the sim plays itself: %s."] = "Talents que la simulation joue elle-même : %s.",
            ["Tanks wear their heaviest armor."] = "Les tanks portent leur armure la plus lourde.",
            ["Target"] = "Cible",
            ["Teal"] = "Turquoise",
            ["The Best in Slot module is off (Modules)."] = "Le module Best in Slot est désactivé (Modules).",
            ["The Best in Slot sim is running: the small window shows how far it is. Take the tour meanwhile; your list is ready when it is done."] = "La simulation BiS est en cours : la petite fenêtre montre son avancement. Faites la visite en attendant ; votre liste sera prête à la fin.",
            ["The Journal module is off (Modules)."] = "Le module Codex est désactivé (Modules).",
            ["The Underbelly"] = "Les Entrailles",
            ["The Wishlist module is off (Modules)."] = "Le module Liste de souhaits est désactivé (Modules).",
            ["The boss, rare or zone that drops it, with the chance."] = "Le boss, le rare ou la zone qui le lâche, avec la chance.",
            ["The bosses and their loot are added as soon as they are seen in the game or revealed."] = "Les boss et leur butin sont ajoutés dès qu’ils sont vus en jeu ou révélés.",
            ["The damage the sim found for the item against what you wear, or that it is on your Best in Slot list."] = "Les dégâts trouvés par la simulation pour l’objet contre votre équipement, ou sa présence dans votre liste Best in Slot.",
            ["The dungeon entrances on the world map, the alert when a wishlist item drops and opening the dungeon you are in."] = "Les entrées de donjon sur la carte du monde, l’alerte quand un objet souhaité tombe et l’ouverture du donjon où vous êtes.",
            ["The filter of your Best in Slot list: the spec it is made for, the armor it takes and where its items may come from. Open it any time: the first time it explains itself."] = "Le filtre de votre liste Best in Slot : la spécialisation visée, l’armure prise en compte et la provenance permise des objets. Ouvrez-le quand vous voulez : il s’explique la première fois.",
            ["The filter of your Best in Slot list: the spec it is made for, the armor it takes and where its items may come from; its second tab orders your stats. Open it any time: the first time it explains itself."] = "Le filtre de votre liste Best in Slot : la spécialisation visée, l’armure prise en compte et la provenance permise des objets ; son second onglet ordonne vos caractéristiques. Ouvrez-le quand vous voulez : il s’explique la première fois.",
            ["The game blocked an action of Lootified (%s). /lf errors shows the details."] = "Le jeu a bloqué une action de Lootified (%s). /lf errors montre les détails.",
            ["The game does not let addons open the world map right now."] = "Le jeu ne laisse pas les addons ouvrir la carte du monde pour l’instant.",
            ["The game does not let addons open the world map right now. The spot is marked: open your world map to see it."] = "Le jeu ne laisse pas les addons ouvrir la carte du monde pour l’instant. L’endroit est marqué : ouvrez votre carte du monde pour le voir.",
            ["The game has no data of this item yet: press Sim again in a moment."] = "Le jeu n’a pas encore de données sur cet objet : appuyez à nouveau sur Sim dans un instant.",
            ["The game has no map data for the open world mobs yet."] = "Le jeu n’a pas encore de données de carte pour les monstres du monde.",
            ["The game has no map position for this spot."] = "Le jeu n’a pas de position sur la carte pour cet endroit.",
            ["The game has not sent all of its data yet."] = "Le jeu n’a pas encore envoyé toutes ses données.",
            ["The game is still loading your spell texts: try again in a moment."] = "Le jeu charge encore les textes de vos sorts : réessayez dans un instant.",
            ["The gear button at the top right opens the settings. Pick a category on the left; every change applies at once."] = "Le bouton engrenage en haut à droite ouvre les réglages. Choisissez une catégorie à gauche ; chaque changement s’applique aussitôt.",
            ["The green arrow marks the items of your Best in Slot list (sort by For you to see the best first)."] = "La flèche verte marque les objets de votre liste Best in Slot (triez par Pour vous pour voir les meilleurs en premier).",
            ["The green arrow marks the items of your Best in Slot list, with the damage they add (sort by For you to see the biggest first)."] = "La flèche verte marque les objets de votre liste Best in Slot, avec les dégâts qu’ils ajoutent (triez par Pour vous pour voir les plus gros en premier).",
            ["The items you starred, grouped by where they drop. You get an alert as soon as one drops."] = "Les objets marqués d’une étoile, groupés selon leur provenance. Vous recevez une alerte dès que l’un tombe.",
            ["The items you starred; the stars, the tooltip mark and the alert when one drops."] = "Les objets marqués d’une étoile ; les étoiles, la marque d’infobulle et l’alerte quand l’un tombe.",
            ["The language is under Language; this tour starts again from Tour & help or with /lf tour. Found a bug or have an idea? Website & Discord are here and behind the ? at the top. Have fun!"] = "La langue est sous Langue ; cette visite se relance depuis Visite & aide ou avec /lf tour. Un bug ou une idée ? Le site & Discord sont ici et derrière le ? en haut. Amusez-vous bien !",
            ["The language of the interface and of the game's names in Lootified."] = "La langue de l’interface et des noms du jeu dans Lootified.",
            ["The last collect was cut off: what it had read is kept. /lf collect again reads the rest."] = "La dernière collecte a été interrompue : ce qu’elle avait lu est conservé. Un nouveau /lf collect lit le reste.",
            ["The level of the target dummy. It stands still, never hits back and is hit from behind."] = "Le niveau du mannequin d’entraînement. Il reste immobile, ne riposte jamais et est frappé de dos.",
            ["The lines Lootified adds to item tooltips, one switch each. The preview shows a real tooltip as you set it."] = "Les lignes que Lootified ajoute aux infobulles d’objets, chacune avec son interrupteur. L’aperçu montre une vraie infobulle selon vos réglages.",
            ["The list of the first start: every armor your class wears, quests, dungeons and rares, drops of 10 % or more."] = "La liste du premier lancement : toutes les armures de votre classe, quêtes, donjons et rares, butins de 10 % ou plus.",
            ["The loot of the dungeons' and raids' bosses and trash."] = "Le butin des boss et des trash des donjons et raids.",
            ["The loot of the open world's rares and other mobs that carry the item."] = "Le butin des rares et autres monstres du monde qui portent l’objet.",
            ["The picked item: its stats and where it drops (click a mob or a quest to open it)."] = "L’objet choisi : ses caractéristiques et où il tombe (cliquez sur un monstre ou une quête pour l’ouvrir).",
            ["The picked item: its stats, where it drops (click a mob or a quest to open it) and the wishlist button. You get an alert when a wishlist item drops."] = "L’objet choisi : ses caractéristiques, où il tombe (cliquez sur un monstre ou une quête pour l’ouvrir) et le bouton de liste de souhaits. Vous recevez une alerte quand un objet souhaité tombe.",
            ["The quests that give the item or need it."] = "Les quêtes qui donnent l’objet ou le demandent.",
            ["The rares and mobs of every zone with their drops and camps."] = "Les rares et monstres de chaque zone avec leur butin et leurs camps.",
            ["The rares and other mobs of every zone with their drops, drop chances and camps on the map. The page shows the zone you are in."] = "Les rares et autres monstres de chaque zone avec leur butin, leurs chances de butin et leurs camps sur la carte. La page montre la zone où vous êtes.",
            ["The same for bosses and rares, for quests (with their chains) and for dungeons, raids and zones. Links between the pages open the right entry."] = "Pareil pour les boss et rares, pour les quêtes (avec leurs suites) et pour les donjons, raids et zones. Les liens entre les pages ouvrent la bonne entrée.",
            ["The set fights in the simulator's planner for its exact damage: the number on the sheet is an estimate from each item simmed alone."] = "L’ensemble combat dans le planificateur du simulateur pour ses dégâts exacts : le chiffre de la fiche est une estimation à partir de chaque objet simulé seul.",
            ["The simulator could not read your character: %s"] = "Le simulateur n’a pas pu lire votre personnage : %s",
            ["The simulator fights with your talents and gear and shows every upgrade in DPS. You run the sims yourself (the Best in Slot sim takes a few minutes): pick it only if you want that."] = "Le simulateur combat avec vos talents et votre équipement et montre chaque amélioration en DPS. Vous lancez les simulations vous-même (la simulation BiS prend quelques minutes) : ne le choisissez que si vous le voulez.",
            ["The simulator has no numbers for this item."] = "Le simulateur n’a pas de valeurs pour cet objet.",
            ["The simulator is calculating"] = "Le simulateur calcule",
            ["The simulator rates your damage. Your upgrades follow your stat weights."] = "Le simulateur évalue vos dégâts. Vos améliorations suivent vos poids de caractéristiques.",
            ["The simulator stopped: %s"] = "Le simulateur s’est arrêté : %s",
            ["The target: %s"] = "La cible : %s",
            ["The tour stopped because of combat. /lf tour starts it again."] = "La visite s’est arrêtée à cause d’un combat. /lf tour la relance.",
            ["These are the bosses, numbered in their order. Click one to see its loot next to the map; click it again to close it."] = "Voici les boss, numérotés dans leur ordre. Cliquez sur l’un pour voir son butin à côté de la carte ; cliquez à nouveau pour le fermer.",
            ["This decides how this character's upgrades show in tooltips, loot rolls, For you and its Best in Slot list."] = "Cela décide comment les améliorations de ce personnage apparaissent dans les infobulles, les jets de butin, Pour vous et sa liste Best in Slot.",
            ["This dungeon has more than one floor: switch between them here. Next to the buttons is the name of the floor you see."] = "Ce donjon a plusieurs niveaux : passez de l’un à l’autre ici. À côté des boutons figure le nom du niveau affiché.",
            ["This is For you, your start page: the dungeons for your level with your upgrades and your next Best in Slot items. Click anything to open it."] = "Voici Pour vous, votre page d’accueil : les donjons de votre niveau avec vos améliorations et vos prochains objets BiS. Cliquez sur n’importe quoi pour l’ouvrir.",
            ["This is For you, your start page: the dungeons for your level. Click anything to open it."] = "Voici Pour vous, votre page d’accueil : les donjons de votre niveau. Cliquez sur n’importe quoi pour l’ouvrir.",
            ["This item is not in the loot data. It may be crafted, sold by a vendor or come from a source that is new in Forever."] = "Cet objet n’est pas dans les données de butin. Il est peut-être fabriqué, vendu par un marchand ou issu d’une source nouvelle dans Forever.",
            ["This item is not in your game client yet (datamined / upcoming)."] = "Cet objet n’est pas encore dans votre client de jeu (extrait des données / à venir).",
            ["This spec fights in Bear Form, which druids learn at level 10. Until then, pick another spec on the Best in Slot sheet."] = "Cette spécialisation combat en forme d’ours, que les druides apprennent au niveau 10. D’ici là, choisissez une autre spécialisation sur la fiche Best in Slot.",
            ["This spec fights in Cat Form, which druids learn at level 20. Until then, pick another spec on the Best in Slot sheet."] = "Cette spécialisation combat en forme de félin, que les druides apprennent au niveau 20. D’ici là, choisissez une autre spécialisation sur la fiche Best in Slot.",
            ["This spec fights in Defensive Stance, which warriors learn at level 10. Until then, pick another spec on the Best in Slot sheet."] = "Cette spécialisation combat en posture défensive, que les guerriers apprennent au niveau 10. D’ici là, choisissez une autre spécialisation sur la fiche Best in Slot.",
            ["This spec fights with a pet, which hunters get at level 10. Until then, pick another spec on the Best in Slot sheet."] = "Cette spécialisation combat avec un familier, que les chasseurs obtiennent au niveau 10. D’ici là, choisissez une autre spécialisation sur la fiche Best in Slot.",
            ["This spec tanks with a shield: put one on, then try again."] = "Cette spécialisation tanke avec un bouclier : équipez-en un, puis réessayez.",
            ["This tour shows every part of Lootified. At the end you see the settings, where you can switch off what you do not need."] = "Cette visite montre chaque partie de Lootified. À la fin, vous voyez les réglages, où vous pouvez désactiver ce dont vous n’avez pas besoin.",
            ["Thrown"] = "Arme de jet",
            ["Tooltips"] = "Infobulles",
            ["Totem"] = "Totem",
            ["Tour & help"] = "Visite & aide",
            ["Trade Goods (Parts)"] = "Artisanat (pièces)",
            ["Trash"] = "Trash",
            ["Trash & zone drops"] = "Trash & butin de zone",
            ["Trash mobs"] = "Trash",
            ["Trinket"] = "Bijou",
            ["Try on"] = "Essayer",
            ["Try on set (Dressing Room)"] = "Essayer l’ensemble (cabine d’essayage)",
            ["Try the name of a dungeon, boss, quest, zone, mob or item. Parts of words work too, e.g. \"vanc\" or \"blade\"."] = "Essayez le nom d’un donjon, boss, quête, zone, monstre ou objet. Les morceaux de mots marchent aussi, p. ex. « vanc » ou « lame ».",
            ["Turbo"] = "Turbo",
            ["Turbo: %d ms per frame, the sim is done soonest, the game can run slower meanwhile."] = "Turbo : %d ms par image, la simulation finit au plus tôt, le jeu peut ralentir pendant ce temps.",
            ["Turn in"] = "À rendre",
            ["Two sets of your own: click a slot to pick any item your character can put on there, or drop an item from your bags on it. The set fights on its own."] = "Deux ensembles perso : cliquez sur un emplacement pour choisir n’importe quel objet que votre personnage peut y équiper, ou déposez-y un objet de vos sacs. L’ensemble combat seul.",
            ["Two-Hand"] = "Deux mains",
            ["Two-hand weapon"] = "Arme à deux mains",
            ["Two-hander in the main hand"] = "Arme à deux mains en main droite",
            ["Type"] = "Type",
            ["Type /lf collect stop to cancel. Please stay logged in."] = "Tapez /lf collect stop pour annuler. Restez connecté, s’il vous plaît.",
            ["Type /reload, then send the file WTF\\Account\\<account>\\SavedVariables\\Lootified.lua."] = "Tapez /reload, puis envoyez le fichier WTF\\Account\\<compte>\\SavedVariables\\Lootified.lua.",
